DROP TABLE IF EXISTS `academic_schedules`;
CREATE TABLE `academic_schedules` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `resource_id` int unsigned NOT NULL,
  `faculty_id` int unsigned DEFAULT NULL,
  `course_code` varchar(20) NOT NULL,
  `course_name` varchar(120) NOT NULL,
  `semester` varchar(20) NOT NULL,
  `day_of_week` tinyint unsigned NOT NULL COMMENT '0=Monday ... 6=Sunday (MySQL WEEKDAY())',
  `start_time` time NOT NULL,
  `end_time` time NOT NULL,
  `valid_from` date NOT NULL,
  `valid_to` date NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_schedules_resource_day` (`resource_id`,`day_of_week`,`start_time`),
  KEY `fk_schedules_faculty` (`faculty_id`),
  CONSTRAINT `fk_schedules_faculty` FOREIGN KEY (`faculty_id`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_schedules_resource` FOREIGN KEY (`resource_id`) REFERENCES `resources` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `chk_schedules_dates` CHECK ((`valid_to` >= `valid_from`)),
  CONSTRAINT `chk_schedules_dow` CHECK ((`day_of_week` between 0 and 6)),
  CONSTRAINT `chk_schedules_time` CHECK ((`end_time` > `start_time`))
) ENGINE=InnoDB AUTO_INCREMENT=41 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

