DELIMITER $$
DROP FUNCTION IF EXISTS `fn_booking_hours`$$
CREATE FUNCTION `fn_booking_hours`(p_start DATETIME, p_end DATETIME) RETURNS decimal(6,2)
    DETERMINISTIC
BEGIN
  RETURN ROUND(TIMESTAMPDIFF(MINUTE, p_start, p_end) / 60, 2);
END$$

DROP FUNCTION IF EXISTS `fn_setting_int`$$
CREATE FUNCTION `fn_setting_int`(p_key VARCHAR(60), p_default INT) RETURNS int
    READS SQL DATA
BEGIN
  DECLARE v_val VARCHAR(255);
  SELECT setting_value INTO v_val FROM system_settings WHERE setting_key = p_key;
  IF v_val IS NULL OR v_val NOT REGEXP '^-?[0-9]+$' THEN
    RETURN p_default;
  END IF;
  RETURN CAST(v_val AS SIGNED);
END$$

DROP FUNCTION IF EXISTS `fn_slot_conflict`$$
CREATE FUNCTION `fn_slot_conflict`(p_resource_id INT UNSIGNED, p_start DATETIME, p_end DATETIME,
                                 p_exclude_booking BIGINT UNSIGNED) RETURNS varchar(20) CHARSET utf8mb4
    READS SQL DATA
BEGIN
  DECLARE v_status VARCHAR(20);
  DECLARE v_cnt INT DEFAULT 0;

  SELECT status INTO v_status FROM resources WHERE id = p_resource_id;
  IF v_status IS NULL THEN RETURN 'NO_RESOURCE'; END IF;
  IF v_status = 'retired' THEN RETURN 'RETIRED'; END IF;

  SELECT COUNT(*) INTO v_cnt
    FROM bookings b
   WHERE b.resource_id = p_resource_id
     AND b.status IN ('pending','approved')
     AND b.start_time < p_end AND b.end_time > p_start
     AND (p_exclude_booking IS NULL OR b.id <> p_exclude_booking);
  IF v_cnt > 0 THEN RETURN 'BOOKING_CONFLICT'; END IF;

  SELECT COUNT(*) INTO v_cnt
    FROM maintenance_requests m
   WHERE m.resource_id = p_resource_id
     AND m.status IN ('open','in_progress')
     AND m.starts_at < p_end
     AND COALESCE(m.expected_end, '9999-12-31 00:00:00') > p_start;
  IF v_cnt > 0 THEN RETURN 'MAINTENANCE'; END IF;

  SELECT COUNT(*) INTO v_cnt
    FROM academic_schedules s
   WHERE s.resource_id = p_resource_id
     AND s.day_of_week = WEEKDAY(p_start)
     AND DATE(p_start) BETWEEN s.valid_from AND s.valid_to
     AND s.start_time < TIME(p_end) AND s.end_time > TIME(p_start);
  IF v_cnt > 0 THEN RETURN 'CLASS_SCHEDULE'; END IF;

  RETURN 'OK';
END$$

DROP PROCEDURE IF EXISTS `sp_cancel_booking`$$
CREATE PROCEDURE `sp_cancel_booking`(
  IN p_booking_id BIGINT UNSIGNED,
  IN p_actor_id   INT UNSIGNED,
  IN p_reason     VARCHAR(255))
BEGIN
  DECLARE v_role VARCHAR(20);
  DECLARE v_owner INT UNSIGNED;
  DECLARE v_status VARCHAR(20);
  DECLARE v_start DATETIME;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    RESIGNAL;
  END;

  SELECT r.name INTO v_role FROM users u JOIN roles r ON r.id = u.role_id WHERE u.id = p_actor_id;
  IF v_role IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'NOT_FOUND: User does not exist';
  END IF;

  SET @sc_actor = p_actor_id;
  START TRANSACTION;

  SELECT user_id, status, start_time INTO v_owner, v_status, v_start
    FROM bookings WHERE id = p_booking_id FOR UPDATE;
  IF v_status IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'NOT_FOUND: Booking does not exist';
  END IF;
  IF v_owner <> p_actor_id AND v_role <> 'admin' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'FORBIDDEN: You can only cancel your own bookings';
  END IF;
  IF v_status NOT IN ('pending','approved') THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'INVALID_STATE: Only pending or approved bookings can be cancelled';
  END IF;
  IF v_role <> 'admin' AND v_start <= NOW() THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'TOO_LATE: A booking that has already started cannot be cancelled';
  END IF;

  UPDATE bookings
     SET status = 'cancelled', cancel_reason = COALESCE(NULLIF(p_reason, ''), 'Cancelled by user'),
         cancelled_at = NOW()
   WHERE id = p_booking_id;
  COMMIT;
END$$

DROP PROCEDURE IF EXISTS `sp_create_booking`$$
CREATE PROCEDURE `sp_create_booking`(
  IN  p_user_id     INT UNSIGNED,
  IN  p_resource_id INT UNSIGNED,
  IN  p_start       DATETIME,
  IN  p_end         DATETIME,
  IN  p_purpose     VARCHAR(255),
  IN  p_attendees   SMALLINT UNSIGNED,
  IN  p_equipment   JSON,
  OUT p_booking_id  BIGINT UNSIGNED,
  OUT p_status      VARCHAR(20))
BEGIN
  DECLARE v_role VARCHAR(20);
  DECLARE v_user_status VARCHAR(20);
  DECLARE v_requires TINYINT(1);
  DECLARE v_lock INT UNSIGNED;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    RESIGNAL;
  END;

  SELECT r.name, u.status INTO v_role, v_user_status
    FROM users u JOIN roles r ON r.id = u.role_id WHERE u.id = p_user_id;
  IF v_role IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'NOT_FOUND: User does not exist';
  END IF;
  IF v_user_status <> 'active' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'FORBIDDEN: Account is suspended';
  END IF;

  SET @sc_actor = p_user_id;
  START TRANSACTION;

  SELECT id, requires_approval INTO v_lock, v_requires
    FROM resources WHERE id = p_resource_id FOR UPDATE;
  IF v_lock IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'NOT_FOUND: Resource does not exist';
  END IF;

  CALL sp_validate_booking_rules(v_role, p_resource_id, p_start, p_end, p_attendees);

  SET p_status = IF(v_requires = 1 AND v_role <> 'admin', 'pending', 'approved');

  INSERT INTO bookings (resource_id, user_id, start_time, end_time, purpose, attendees, status)
  VALUES (p_resource_id, p_user_id, p_start, p_end, p_purpose, p_attendees, p_status);
  SET p_booking_id = LAST_INSERT_ID();

  IF p_equipment IS NOT NULL AND JSON_LENGTH(p_equipment) > 0 THEN
    IF EXISTS (
      SELECT 1
        FROM JSON_TABLE(p_equipment, '$[*]' COLUMNS (eid INT UNSIGNED PATH '$.equipmentId', qty INT PATH '$.quantity')) j
        LEFT JOIN equipment e ON e.id = j.eid
       WHERE e.id IS NULL OR e.resource_id <> p_resource_id OR e.bookable_addon = 0
          OR e.status <> 'operational' OR j.qty IS NULL OR j.qty < 1) THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'EQUIPMENT_INVALID: One or more equipment items cannot be requested for this resource';
    END IF;

    IF EXISTS (
      SELECT 1
        FROM (SELECT eid, SUM(qty) AS qty
                FROM JSON_TABLE(p_equipment, '$[*]' COLUMNS (eid INT UNSIGNED PATH '$.equipmentId', qty INT PATH '$.quantity')) x
               GROUP BY eid) j
        JOIN equipment e ON e.id = j.eid
       WHERE j.qty > e.quantity_total - COALESCE((
              SELECT SUM(be.quantity)
                FROM booking_equipment be JOIN bookings b ON b.id = be.booking_id
               WHERE be.equipment_id = e.id AND b.status IN ('pending','approved')
                 AND b.start_time < p_end AND b.end_time > p_start), 0)) THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'EQUIPMENT_UNAVAILABLE: Requested equipment quantity is not available in this time slot';
    END IF;

    INSERT INTO booking_equipment (booking_id, equipment_id, quantity)
    SELECT p_booking_id, eid, SUM(qty)
      FROM JSON_TABLE(p_equipment, '$[*]' COLUMNS (eid INT UNSIGNED PATH '$.equipmentId', qty INT PATH '$.quantity')) j
     GROUP BY eid;
  END IF;

  IF p_status = 'approved' THEN
    INSERT INTO booking_approvals (booking_id, admin_id, decision, remarks)
    VALUES (p_booking_id, NULL, 'auto_approved', 'Approved automatically by policy');
  END IF;

  COMMIT;
END$$

DROP PROCEDURE IF EXISTS `sp_decide_booking`$$
CREATE PROCEDURE `sp_decide_booking`(
  IN p_booking_id BIGINT UNSIGNED,
  IN p_admin_id   INT UNSIGNED,
  IN p_decision   VARCHAR(10),
  IN p_remarks    VARCHAR(255))
BEGIN
  DECLARE v_admin_role VARCHAR(20);
  DECLARE v_status VARCHAR(20);
  DECLARE v_resource INT UNSIGNED;
  DECLARE v_start DATETIME;
  DECLARE v_end DATETIME;
  DECLARE v_conflict VARCHAR(20);
  DECLARE v_lock INT UNSIGNED;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    RESIGNAL;
  END;

  IF p_decision NOT IN ('approved','rejected') THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'VALIDATION: Decision must be approved or rejected';
  END IF;
  SELECT r.name INTO v_admin_role FROM users u JOIN roles r ON r.id = u.role_id WHERE u.id = p_admin_id;
  IF v_admin_role IS NULL OR v_admin_role <> 'admin' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'FORBIDDEN: Only administrators can decide bookings';
  END IF;

  SET @sc_actor = p_admin_id;
  START TRANSACTION;

  SELECT status, resource_id, start_time, end_time
    INTO v_status, v_resource, v_start, v_end
    FROM bookings WHERE id = p_booking_id FOR UPDATE;
  IF v_status IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'NOT_FOUND: Booking does not exist';
  END IF;
  IF v_status <> 'pending' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'INVALID_STATE: Only pending bookings can be approved or rejected';
  END IF;

  IF p_decision = 'approved' THEN
    SELECT id INTO v_lock FROM resources WHERE id = v_resource FOR UPDATE;
    IF v_start <= NOW() THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'BOOKING_EXPIRED: The requested slot has already started';
    END IF;
    SET v_conflict = fn_slot_conflict(v_resource, v_start, v_end, p_booking_id);
    IF v_conflict <> 'OK' THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'CONFLICT: Slot is no longer free (maintenance, class schedule or another booking)';
    END IF;
  END IF;


  INSERT INTO booking_approvals (booking_id, admin_id, decision, remarks)
  VALUES (p_booking_id, p_admin_id, p_decision, p_remarks);

  UPDATE bookings SET status = p_decision WHERE id = p_booking_id;
  COMMIT;
END$$

DROP PROCEDURE IF EXISTS `sp_housekeeping`$$
CREATE PROCEDURE `sp_housekeeping`()
BEGIN
  DECLARE v_completed INT DEFAULT 0;
  DECLARE v_expired INT DEFAULT 0;

  UPDATE bookings SET status = 'completed'
   WHERE status = 'approved' AND end_time < NOW();
  SET v_completed = ROW_COUNT();

  UPDATE bookings
     SET status = 'cancelled', cancelled_at = NOW(),
         cancel_reason = 'Expired: no decision was made before the start time'
   WHERE status = 'pending' AND start_time < NOW();
  SET v_expired = ROW_COUNT();

  UPDATE resources r SET r.status = IF(EXISTS(
            SELECT 1 FROM maintenance_requests m
             WHERE m.resource_id = r.id AND m.status IN ('open','in_progress')
               AND m.starts_at <= NOW() AND (m.expected_end IS NULL OR m.expected_end > NOW())),
          'maintenance', 'available')
   WHERE r.status <> 'retired';

  DELETE FROM revoked_tokens WHERE expires_at < NOW();
  DELETE FROM password_reset_tokens WHERE expires_at < DATE_SUB(NOW(), INTERVAL 1 DAY);

  SELECT v_completed AS completed_bookings, v_expired AS expired_bookings;
END$$

DROP PROCEDURE IF EXISTS `sp_resource_utilization`$$
CREATE PROCEDURE `sp_resource_utilization`(IN p_from DATE, IN p_to DATE)
BEGIN
  DECLARE v_hours_per_day INT;
  SET v_hours_per_day = GREATEST(fn_setting_int('day_end_hour', 20) - fn_setting_int('day_start_hour', 8), 1);

  WITH RECURSIVE days AS (
    SELECT p_from AS d
    UNION ALL
    SELECT DATE_ADD(d, INTERVAL 1 DAY) FROM days WHERE d < p_to
  ),
  open_days AS (SELECT COUNT(*) AS n FROM days WHERE WEEKDAY(d) < 6),
  class_hours AS (
    SELECT s.resource_id, SUM(TIME_TO_SEC(TIMEDIFF(s.end_time, s.start_time)) / 3600) AS hrs
      FROM academic_schedules s
      JOIN days ON WEEKDAY(days.d) = s.day_of_week AND days.d BETWEEN s.valid_from AND s.valid_to
     GROUP BY s.resource_id
  ),
  booked AS (
    SELECT b.resource_id, COUNT(*) AS n, SUM(fn_booking_hours(b.start_time, b.end_time)) AS hrs
      FROM bookings b
     WHERE b.status IN ('approved','completed') AND DATE(b.start_time) BETWEEN p_from AND p_to
     GROUP BY b.resource_id
  )
  SELECT r.id, r.code, r.name, c.name AS category, c.kind,
         COALESCE(bk.n, 0) AS bookings,
         ROUND(COALESCE(bk.hrs, 0), 2) AS booked_hours,
         ROUND(COALESCE(ch.hrs, 0), 2) AS class_hours,
         (od.n * v_hours_per_day) AS available_hours,
         LEAST(100, ROUND(100 * (COALESCE(bk.hrs, 0) + COALESCE(ch.hrs, 0)) / (od.n * v_hours_per_day), 1)) AS utilization_pct
    FROM resources r
    JOIN resource_categories c ON c.id = r.category_id
    CROSS JOIN open_days od
    LEFT JOIN booked bk ON bk.resource_id = r.id
    LEFT JOIN class_hours ch ON ch.resource_id = r.id
   WHERE r.status <> 'retired'
   ORDER BY utilization_pct DESC, r.name;
END$$

DROP PROCEDURE IF EXISTS `sp_update_booking`$$
CREATE PROCEDURE `sp_update_booking`(
  IN p_booking_id BIGINT UNSIGNED,
  IN p_user_id    INT UNSIGNED,
  IN p_start      DATETIME,
  IN p_end        DATETIME,
  IN p_purpose    VARCHAR(255),
  IN p_attendees  SMALLINT UNSIGNED)
BEGIN
  DECLARE v_role VARCHAR(20);
  DECLARE v_owner INT UNSIGNED;
  DECLARE v_status VARCHAR(20);
  DECLARE v_resource INT UNSIGNED;
  DECLARE v_lock INT UNSIGNED;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    RESIGNAL;
  END;

  SELECT r.name INTO v_role FROM users u JOIN roles r ON r.id = u.role_id WHERE u.id = p_user_id;
  SET @sc_actor = p_user_id;
  START TRANSACTION;

  SELECT user_id, status, resource_id INTO v_owner, v_status, v_resource
    FROM bookings WHERE id = p_booking_id FOR UPDATE;
  IF v_status IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'NOT_FOUND: Booking does not exist';
  END IF;
  IF v_owner <> p_user_id THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'FORBIDDEN: You can only edit your own bookings';
  END IF;
  IF v_status <> 'pending' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'INVALID_STATE: Only pending bookings can be edited';
  END IF;

  SELECT id INTO v_lock FROM resources WHERE id = v_resource FOR UPDATE;
  CALL sp_validate_booking_rules(v_role, v_resource, p_start, p_end, p_attendees);

  UPDATE bookings
     SET start_time = p_start, end_time = p_end, purpose = p_purpose, attendees = p_attendees
   WHERE id = p_booking_id;
  COMMIT;
END$$

DROP PROCEDURE IF EXISTS `sp_validate_booking_rules`$$
CREATE PROCEDURE `sp_validate_booking_rules`(
  IN p_role VARCHAR(20), IN p_resource_id INT UNSIGNED,
  IN p_start DATETIME, IN p_end DATETIME, IN p_attendees SMALLINT UNSIGNED)
BEGIN
  DECLARE v_capacity SMALLINT UNSIGNED;
  DECLARE v_status VARCHAR(20);
  DECLARE v_max_hours INT;
  DECLARE v_window_days INT;
  DECLARE v_day_start INT;
  DECLARE v_day_end INT;

  SELECT capacity, status INTO v_capacity, v_status FROM resources WHERE id = p_resource_id;
  IF v_capacity IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'NOT_FOUND: Resource does not exist';
  END IF;
  IF v_status = 'retired' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'RESOURCE_RETIRED: This resource is no longer available for booking';
  END IF;
  IF p_end <= p_start THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'INVALID_TIME: End time must be after start time';
  END IF;
  IF DATE(p_start) <> DATE(p_end) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'INVALID_TIME: A booking must start and end on the same day';
  END IF;
  IF p_start <= NOW() THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'INVALID_TIME: Bookings must start in the future';
  END IF;
  IF p_attendees > v_capacity THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'CAPACITY_EXCEEDED: Attendees exceed the capacity of this resource';
  END IF;

  SET v_max_hours   = IF(p_role = 'faculty', fn_setting_int('max_hours_faculty', 6),
                      IF(p_role = 'admin',   fn_setting_int('max_hours_faculty', 6) * 2,
                                             fn_setting_int('max_hours_student', 3)));
  SET v_window_days = fn_setting_int('booking_window_days', 30);
  SET v_day_start   = fn_setting_int('day_start_hour', 8);
  SET v_day_end     = fn_setting_int('day_end_hour', 20);

  IF TIMESTAMPDIFF(MINUTE, p_start, p_end) > v_max_hours * 60 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'DURATION_EXCEEDED: Booking is longer than the maximum allowed for your role';
  END IF;
  IF DATE(p_start) > DATE_ADD(CURDATE(), INTERVAL v_window_days DAY) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'OUTSIDE_WINDOW: Bookings cannot be made this far in advance';
  END IF;
  IF TIME_TO_SEC(TIME(p_start)) < v_day_start * 3600 OR TIME_TO_SEC(TIME(p_end)) > v_day_end * 3600 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'OUTSIDE_HOURS: Bookings must fall within campus operating hours';
  END IF;
END$$

DELIMITER ;

DROP VIEW IF EXISTS `v_booking_details`;
CREATE VIEW `v_booking_details` AS select `b`.`id` AS `id`,`b`.`booking_code` AS `booking_code`,`b`.`status` AS `status`,`b`.`start_time` AS `start_time`,`b`.`end_time` AS `end_time`,`b`.`purpose` AS `purpose`,`b`.`attendees` AS `attendees`,`b`.`cancel_reason` AS `cancel_reason`,`b`.`cancelled_at` AS `cancelled_at`,`b`.`created_at` AS `created_at`,`b`.`updated_at` AS `updated_at`,`fn_booking_hours`(`b`.`start_time`,`b`.`end_time`) AS `hours`,`u`.`id` AS `user_id`,`u`.`full_name` AS `user_name`,`u`.`email` AS `user_email`,`rl`.`name` AS `user_role`,`d`.`name` AS `department_name`,`r`.`id` AS `resource_id`,`r`.`code` AS `resource_code`,`r`.`name` AS `resource_name`,`c`.`name` AS `category_name`,`c`.`kind` AS `category_kind`,`rm`.`room_number` AS `room_number`,`bl`.`name` AS `building_name`,`bl`.`code` AS `building_code`,`ap`.`decision` AS `decision`,`ap`.`remarks` AS `decision_remarks`,`ap`.`decided_at` AS `decided_at`,`adm`.`full_name` AS `decided_by_name` from (((((((((`bookings` `b` join `users` `u` on((`u`.`id` = `b`.`user_id`))) join `roles` `rl` on((`rl`.`id` = `u`.`role_id`))) left join `departments` `d` on((`d`.`id` = `u`.`department_id`))) join `resources` `r` on((`r`.`id` = `b`.`resource_id`))) join `resource_categories` `c` on((`c`.`id` = `r`.`category_id`))) join `rooms` `rm` on((`rm`.`id` = `r`.`room_id`))) join `buildings` `bl` on((`bl`.`id` = `rm`.`building_id`))) left join `booking_approvals` `ap` on((`ap`.`booking_id` = `b`.`id`))) left join `users` `adm` on((`adm`.`id` = `ap`.`admin_id`)));

DROP VIEW IF EXISTS `v_monthly_booking_trends`;
CREATE VIEW `v_monthly_booking_trends` AS select date_format(`bookings`.`start_time`,'%Y-%m') AS `month_key`,count(0) AS `total`,sum((`bookings`.`status` in ('approved','completed'))) AS `approved`,sum((`bookings`.`status` = 'rejected')) AS `rejected`,sum((`bookings`.`status` = 'cancelled')) AS `cancelled`,sum((`bookings`.`status` = 'pending')) AS `pending` from `bookings` group by date_format(`bookings`.`start_time`,'%Y-%m');

DROP VIEW IF EXISTS `v_popular_resources`;
CREATE VIEW `v_popular_resources` AS with `usage_stats` as (select `r`.`id` AS `id`,`r`.`code` AS `code`,`r`.`name` AS `name`,`c`.`name` AS `category_name`,count(`b`.`id`) AS `total_bookings`,coalesce(sum(`fn_booking_hours`(`b`.`start_time`,`b`.`end_time`)),0) AS `total_hours` from ((`resources` `r` join `resource_categories` `c` on((`c`.`id` = `r`.`category_id`))) left join `bookings` `b` on(((`b`.`resource_id` = `r`.`id`) and (`b`.`status` in ('approved','completed'))))) group by `r`.`id`,`r`.`code`,`r`.`name`,`c`.`name`) select `usage_stats`.`id` AS `id`,`usage_stats`.`code` AS `code`,`usage_stats`.`name` AS `name`,`usage_stats`.`category_name` AS `category_name`,`usage_stats`.`total_bookings` AS `total_bookings`,`usage_stats`.`total_hours` AS `total_hours`,rank() OVER (ORDER BY `usage_stats`.`total_bookings` desc )  AS `popularity_rank` from `usage_stats`;

DROP VIEW IF EXISTS `v_resource_catalog`;
CREATE VIEW `v_resource_catalog` AS select `r`.`id` AS `id`,`r`.`code` AS `code`,`r`.`name` AS `name`,`r`.`description` AS `description`,`r`.`capacity` AS `capacity`,`r`.`status` AS `status`,`r`.`requires_approval` AS `requires_approval`,`c`.`id` AS `category_id`,`c`.`name` AS `category_name`,`c`.`kind` AS `category_kind`,`c`.`icon` AS `category_icon`,`rm`.`id` AS `room_id`,`rm`.`room_number` AS `room_number`,`rm`.`floor_no` AS `floor_no`,`bl`.`id` AS `building_id`,`bl`.`name` AS `building_name`,`bl`.`code` AS `building_code`,`d`.`id` AS `department_id`,`d`.`name` AS `department_name`,(select count(0) from `equipment` `e` where ((`e`.`resource_id` = `r`.`id`) and (`e`.`status` <> 'retired'))) AS `equipment_count`,(select count(0) from `bookings` `b` where ((`b`.`resource_id` = `r`.`id`) and (`b`.`status` in ('pending','approved')) and (`b`.`start_time` >= now()))) AS `upcoming_bookings`,`r`.`created_at` AS `created_at` from ((((`resources` `r` join `resource_categories` `c` on((`c`.`id` = `r`.`category_id`))) join `rooms` `rm` on((`rm`.`id` = `r`.`room_id`))) join `buildings` `bl` on((`bl`.`id` = `rm`.`building_id`))) left join `departments` `d` on((`d`.`id` = `r`.`department_id`)));

DROP VIEW IF EXISTS `v_user_booking_stats`;
CREATE VIEW `v_user_booking_stats` AS select `u`.`id` AS `user_id`,`u`.`full_name` AS `full_name`,`rl`.`name` AS `role_name`,count(`b`.`id`) AS `total_bookings`,sum((`b`.`status` = 'pending')) AS `pending`,sum((`b`.`status` = 'approved')) AS `approved`,sum((`b`.`status` = 'completed')) AS `completed`,sum((`b`.`status` = 'rejected')) AS `rejected`,sum((`b`.`status` = 'cancelled')) AS `cancelled` from ((`users` `u` join `roles` `rl` on((`rl`.`id` = `u`.`role_id`))) left join `bookings` `b` on((`b`.`user_id` = `u`.`id`))) group by `u`.`id`,`u`.`full_name`,`rl`.`name`;

DELIMITER $$
DROP TRIGGER IF EXISTS `trg_bookings_bi`$$
CREATE TRIGGER `trg_bookings_bi` BEFORE INSERT ON `bookings` FOR EACH ROW BEGIN
  DECLARE v_lock INT UNSIGNED;
  DECLARE v_conflict VARCHAR(20);
  DECLARE v_msg VARCHAR(200);

  IF NEW.booking_code IS NULL OR NEW.booking_code = '' THEN
    SET NEW.booking_code = CONCAT('BK-', DATE_FORMAT(NOW(), '%y%m'), '-',
                                  UPPER(SUBSTRING(REPLACE(UUID(), '-', ''), 1, 6)));
  END IF;

  IF NEW.status IN ('pending','approved') THEN
    SELECT id INTO v_lock FROM resources WHERE id = NEW.resource_id FOR UPDATE;
    SET v_conflict = fn_slot_conflict(NEW.resource_id, NEW.start_time, NEW.end_time, NULL);
    IF v_conflict <> 'OK' THEN
      SET v_msg = CASE v_conflict
        WHEN 'BOOKING_CONFLICT' THEN 'BOOKING_CONFLICT: This resource is already booked for an overlapping time slot'
        WHEN 'MAINTENANCE'      THEN 'MAINTENANCE: This resource is under maintenance during the requested time'
        WHEN 'CLASS_SCHEDULE'   THEN 'CLASS_SCHEDULE: A scheduled class occupies this resource during the requested time'
        WHEN 'RETIRED'          THEN 'RESOURCE_RETIRED: This resource is no longer available for booking'
        ELSE 'NOT_FOUND: Resource does not exist' END;
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = v_msg;
    END IF;
  END IF;
END$$

DROP TRIGGER IF EXISTS `trg_bookings_ai`$$
CREATE TRIGGER `trg_bookings_ai` AFTER INSERT ON `bookings` FOR EACH ROW BEGIN
  DECLARE v_res VARCHAR(120);
  DECLARE v_user VARCHAR(120);
  DECLARE v_when VARCHAR(80);

  IF COALESCE(@sc_seeding, 0) = 0 THEN
    SELECT name INTO v_res FROM resources WHERE id = NEW.resource_id;
    SELECT full_name INTO v_user FROM users WHERE id = NEW.user_id;
    SET v_when = CONCAT(DATE_FORMAT(NEW.start_time, '%d %b %Y, %h:%i %p'), ' - ', DATE_FORMAT(NEW.end_time, '%h:%i %p'));

    INSERT INTO booking_status_history (booking_id, old_status, new_status, changed_by)
    VALUES (NEW.id, NULL, NEW.status, COALESCE(@sc_actor, NEW.user_id));

    INSERT INTO notifications (user_id, type, title, message, booking_id)
    VALUES (NEW.user_id,
            IF(NEW.status = 'approved', 'booking_approved', 'booking_created'),
            IF(NEW.status = 'approved', 'Booking confirmed', 'Booking request received'),
            IF(NEW.status = 'approved',
               CONCAT(v_res, ' is confirmed for ', v_when, '.'),
               CONCAT('Your request for ', v_res, ' on ', v_when, ' is awaiting administrator approval.')),
            NEW.id);

    IF NEW.status = 'pending' THEN
      INSERT INTO notifications (user_id, type, title, message, booking_id)
      SELECT u.id, 'booking_created', 'New booking awaiting approval',
             CONCAT(v_user, ' requested ', v_res, ' on ', v_when, '.'), NEW.id
        FROM users u JOIN roles r ON r.id = u.role_id
       WHERE r.name = 'admin' AND u.status = 'active' AND u.id <> NEW.user_id;
    END IF;
  END IF;
END$$

DROP TRIGGER IF EXISTS `trg_bookings_bu`$$
CREATE TRIGGER `trg_bookings_bu` BEFORE UPDATE ON `bookings` FOR EACH ROW BEGIN
  DECLARE v_lock INT UNSIGNED;
  DECLARE v_conflict VARCHAR(20);
  DECLARE v_msg VARCHAR(200);

  IF OLD.status IN ('rejected','cancelled','completed') AND NEW.status IN ('pending','approved') THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'INVALID_STATE: A closed booking cannot be re-opened';
  END IF;

  IF NEW.status IN ('pending','approved')
     AND (NEW.start_time <> OLD.start_time OR NEW.end_time <> OLD.end_time OR NEW.resource_id <> OLD.resource_id) THEN
    SELECT id INTO v_lock FROM resources WHERE id = NEW.resource_id FOR UPDATE;
    SET v_conflict = fn_slot_conflict(NEW.resource_id, NEW.start_time, NEW.end_time, OLD.id);
    IF v_conflict <> 'OK' THEN
      SET v_msg = CASE v_conflict
        WHEN 'BOOKING_CONFLICT' THEN 'BOOKING_CONFLICT: This resource is already booked for an overlapping time slot'
        WHEN 'MAINTENANCE'      THEN 'MAINTENANCE: This resource is under maintenance during the requested time'
        WHEN 'CLASS_SCHEDULE'   THEN 'CLASS_SCHEDULE: A scheduled class occupies this resource during the requested time'
        ELSE 'RESOURCE_RETIRED: This resource is no longer available for booking' END;
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = v_msg;
    END IF;
  END IF;
END$$

DROP TRIGGER IF EXISTS `trg_bookings_au`$$
CREATE TRIGGER `trg_bookings_au` AFTER UPDATE ON `bookings` FOR EACH ROW BEGIN
  DECLARE v_res VARCHAR(120);
  DECLARE v_when VARCHAR(80);
  DECLARE v_remarks VARCHAR(255);

  IF COALESCE(@sc_seeding, 0) = 0 AND NEW.status <> OLD.status THEN
    SELECT name INTO v_res FROM resources WHERE id = NEW.resource_id;
    SET v_when = CONCAT(DATE_FORMAT(NEW.start_time, '%d %b %Y, %h:%i %p'), ' - ', DATE_FORMAT(NEW.end_time, '%h:%i %p'));

    INSERT INTO booking_status_history (booking_id, old_status, new_status, changed_by)
    VALUES (NEW.id, OLD.status, NEW.status, @sc_actor);

    IF NEW.status IN ('approved','rejected') THEN
      SELECT remarks INTO v_remarks FROM booking_approvals WHERE booking_id = NEW.id;
      INSERT INTO notifications (user_id, type, title, message, booking_id)
      VALUES (NEW.user_id,
              IF(NEW.status = 'approved', 'booking_approved', 'booking_rejected'),
              IF(NEW.status = 'approved', 'Booking approved', 'Booking rejected'),
              CONCAT(v_res, ' on ', v_when, IF(NEW.status = 'approved', ' was approved.', ' was rejected.'),
                     IF(v_remarks IS NULL OR v_remarks = '', '', CONCAT(' Remarks: ', v_remarks))),
              NEW.id);
    ELSEIF NEW.status = 'cancelled' THEN
      INSERT INTO notifications (user_id, type, title, message, booking_id)
      VALUES (NEW.user_id, 'booking_cancelled', 'Booking cancelled',
              CONCAT(v_res, ' on ', v_when, ' was cancelled.',
                     IF(NEW.cancel_reason IS NULL, '', CONCAT(' Reason: ', NEW.cancel_reason))),
              NEW.id);
    END IF;
  END IF;
END$$

DROP TRIGGER IF EXISTS `trg_maintenance_ai`$$
CREATE TRIGGER `trg_maintenance_ai` AFTER INSERT ON `maintenance_requests` FOR EACH ROW BEGIN
  DECLARE v_res VARCHAR(120);

  UPDATE resources r
     SET r.status = IF(EXISTS(
           SELECT 1 FROM maintenance_requests m
            WHERE m.resource_id = r.id AND m.status IN ('open','in_progress')
              AND m.starts_at <= NOW() AND (m.expected_end IS NULL OR m.expected_end > NOW())),
         'maintenance', 'available')
   WHERE r.id = NEW.resource_id AND r.status <> 'retired';

  IF COALESCE(@sc_seeding, 0) = 0 THEN
    SELECT name INTO v_res FROM resources WHERE id = NEW.resource_id;
    INSERT INTO notifications (user_id, type, title, message, maintenance_id)
    SELECT u.id, 'maintenance_update',
           IF(NEW.status = 'reported', 'New maintenance report', 'Maintenance scheduled'),
           CONCAT(v_res, ': ', NEW.title, ' (priority ', NEW.priority, ').'), NEW.id
      FROM users u JOIN roles r ON r.id = u.role_id
     WHERE r.name = 'admin' AND u.status = 'active';
  END IF;
END$$

DROP TRIGGER IF EXISTS `trg_maintenance_au`$$
CREATE TRIGGER `trg_maintenance_au` AFTER UPDATE ON `maintenance_requests` FOR EACH ROW BEGIN
  DECLARE v_res VARCHAR(120);

  UPDATE resources r
     SET r.status = IF(EXISTS(
           SELECT 1 FROM maintenance_requests m
            WHERE m.resource_id = r.id AND m.status IN ('open','in_progress')
              AND m.starts_at <= NOW() AND (m.expected_end IS NULL OR m.expected_end > NOW())),
         'maintenance', 'available')
   WHERE r.id IN (NEW.resource_id, OLD.resource_id) AND r.status <> 'retired';

  IF COALESCE(@sc_seeding, 0) = 0 AND NEW.status <> OLD.status AND NEW.reported_by IS NOT NULL THEN
    SELECT name INTO v_res FROM resources WHERE id = NEW.resource_id;
    INSERT INTO notifications (user_id, type, title, message, maintenance_id)
    VALUES (NEW.reported_by, 'maintenance_update', 'Maintenance update',
            CONCAT('Your report "', NEW.title, '" for ', v_res, ' is now ', REPLACE(NEW.status, '_', ' '), '.'),
            NEW.id);
  END IF;
END$$

DELIMITER ;

SET FOREIGN_KEY_CHECKS = 1;
